#[test]
fn test_reduce_proj_index_comparison() {
    // Kill mutant: reduce_proj < with <=
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};
    use crate::level::Level;

    let mut env = Environment::new();

    // Create a 3-field structure
    // Fields are Type (Sort(1)), so result must be Sort(2) = Type 1
    let triple = Name::from_string("Triple");
    let triple_type = Expr::sort(Level::succ(Level::succ(Level::zero())));

    // mk : Type → Type → Type → Triple
    let mk_type = Expr::pi(
        BinderInfo::Default,
        Expr::type_(),
        Expr::pi(
            BinderInfo::Default,
            Expr::type_(),
            Expr::pi(
                BinderInfo::Default,
                Expr::type_(),
                Expr::const_(triple.clone(), vec![]),
            ),
        ),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: triple.clone(),
            type_: triple_type,
            constructors: vec![Constructor {
                name: Name::from_string("Triple.mk"),
                type_: mk_type,
            }],
        }],
    };

    env.add_inductive(decl).unwrap();
    let tc = TypeChecker::new(&env);

    // Build Triple.mk val0 val1 val2
    let mk = Expr::const_(Name::from_string("Triple.mk"), vec![]);
    let val0 = Expr::prop();
    let val1 = Expr::type_();
    let val2 = Expr::from_kind(ExprKind::Sort(Level::succ(Level::succ(Level::zero()))));

    // Build with correct arity (3 fields)
    let triple_val = Expr::app(
        Expr::app(Expr::app(mk, val0.clone()), val1.clone()),
        val2.clone(),
    );

    // Test all three projections
    let proj0 = Expr::proj(triple.clone(), 0, triple_val.clone());
    let proj1 = Expr::proj(triple.clone(), 1, triple_val.clone());
    let proj2 = Expr::proj(triple.clone(), 2, triple_val);

    let result0 = tc.whnf(&proj0);
    let result1 = tc.whnf(&proj1);
    let result2 = tc.whnf(&proj2);

    // Each projection should return the correct field
    assert_eq!(result0, val0, "proj.0 should return first field");
    assert_eq!(result1, val1, "proj.1 should return second field");
    assert_eq!(result2, val2, "proj.2 should return third field");
}

#[test]
fn test_reduce_proj_index_boundary() {
    // Kill mutant: reduce_proj < with <= (line 808)
    // Tests that field_idx < args.len() (not <=)

    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    // Create a structure with 2 fields: Pair
    let pair = Name::from_string("Pair");
    let pair_ref = Expr::const_(pair.clone(), vec![]);
    let pair_mk_type = Expr::arrow(Expr::prop(), Expr::arrow(Expr::prop(), pair_ref.clone()));

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: pair.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: Name::from_string("Pair.mk"),
                type_: pair_mk_type,
            }],
        }],
    };
    env.add_inductive(decl).unwrap();

    let tc = TypeChecker::new(&env);

    // Create Pair.mk p1 p2
    let mk = Expr::const_(Name::from_string("Pair.mk"), vec![]);
    let p1 = Expr::prop();
    let p2 = Expr::type_();
    let pair_val = Expr::app(Expr::app(mk, p1.clone()), p2.clone());

    // Projection 0 should work (field_idx = 0, args.len() = 2, 0 < 2)
    let proj0 = Expr::proj(pair.clone(), 0, pair_val.clone());
    let result0 = tc.whnf(&proj0);
    assert_eq!(result0, p1);

    // Projection 1 should work (field_idx = 1, args.len() = 2, 1 < 2)
    let proj1 = Expr::proj(pair.clone(), 1, pair_val.clone());
    let result1 = tc.whnf(&proj1);
    assert_eq!(result1, p2);

    // Projection 2 should NOT reduce (field_idx = 2, args.len() = 2, 2 < 2 is FALSE)
    let proj2 = Expr::proj(pair.clone(), 2, pair_val.clone());
    let result2 = tc.whnf(&proj2);
    // Should not have reduced - still a projection
    assert!(matches!(&result2.kind, ExprKind::Proj(_, _, _)));
}

/// Test that projection from Prop type with Prop field succeeds (valid case).
///
/// This is the counterpart to test_error_invalid_proj_from_prop, showing that
/// Prop-to-Prop projections are allowed.
#[test]
fn test_valid_proj_prop_to_prop() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    // Create a simple Prop-typed structure with a Prop field.
    // This mimics the common pattern in Lean like And/Or/Exists.
    //
    // We need a Prop to project from. Use True : Prop as a placeholder.
    let true_name = Name::from_string("True");
    let true_decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: true_name.clone(),
            type_: Expr::prop(),
            constructors: vec![Constructor {
                name: Name::from_string("True.intro"),
                type_: Expr::const_(true_name.clone(), vec![]),
            }],
        }],
    };
    env.add_inductive(true_decl).unwrap();

    // PropWrapper : Prop
    // PropWrapper.mk : True → PropWrapper
    //
    // The field has type True : Prop, which IS in Prop.
    let pw_name = Name::from_string("PropWrapper");
    let true_ty = Expr::const_(true_name.clone(), vec![]);

    let pw_mk_type = Expr::pi(
        BinderInfo::Default,
        true_ty.clone(), // proof : True (IS in Prop!)
        Expr::const_(pw_name.clone(), vec![]),
    );

    let pw_decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: pw_name.clone(),
            type_: Expr::prop(), // Type is Prop
            constructors: vec![Constructor {
                name: Name::from_string("PropWrapper.mk"),
                type_: pw_mk_type,
            }],
        }],
    };
    env.add_inductive(pw_decl).unwrap();

    let tc = TypeChecker::new(&env);

    // Create a value: PropWrapper.mk True.intro
    let intro = Expr::const_(Name::from_string("True.intro"), vec![]);
    let mk = Expr::const_(Name::from_string("PropWrapper.mk"), vec![]);
    let pw_val = Expr::app(mk, intro);

    // Project field 0 (the True field from a Prop-typed structure)
    // This SHOULD succeed because both are Props.
    let proj = Expr::proj(pw_name.clone(), 0, pw_val);
    let result = tc.infer_type(&proj);

    assert!(
        result.is_ok(),
        "Prop-to-Prop projection should succeed, got {result:?}"
    );

    // Verify the projected type is True
    let projected_type = result.unwrap();
    assert_eq!(
        projected_type,
        Expr::const_(true_name, vec![]),
        "Projected type should be True"
    );
}

/// Build a minimal environment with String, List, Char, Nat for projection tests.
fn build_string_env() -> Environment {
    let mut env = Environment::new();
    env.init_string().unwrap();
    env
}

/// Regression test for #1409: projection reduction must lower string literals
/// to constructor form before field extraction.
///
/// Per Lean 4 type_checker.cpp:360-361, `reduce_proj_core` calls
/// `string_lit_to_constructor` when the expression is a string literal.
/// Without this lowering, `Proj(String, 0, Lit(String("hi")))` cannot reduce.
#[test]
fn test_proj_string_literal_lowering() {
    let env = build_string_env();
    let tc = TypeChecker::new(&env);

    let string_name = Name::from_string("String");

    // Proj(String, 0, "hi") should reduce to the List Char form of "hi"
    let proj = Expr::proj(string_name.clone(), 0, Expr::str_lit("hi"));
    let result = tc.whnf(&proj);

    // The result must NOT be a Proj expression — it must have reduced
    assert!(
        !matches!(&result.kind, ExprKind::Proj(..)),
        "Proj on string literal should reduce, but got unreduced Proj: {result:?}"
    );

    // The result should be a List.cons application (since "hi" has chars)
    // String.mk takes one arg (List Char), so field 0 is that list.
    // After lowering "hi", we get String.ofList (List.cons ...) which whnf reduces
    // to String.mk (List.cons ...), then projection extracts the list.
    let head = result.get_app_fn();
    assert!(
        matches!(&head.kind, ExprKind::Const(n, _) if n == &Name::from_string("List.cons")),
        "Projected field should be a List.cons application (character list), got head: {head:?}"
    );

    // Also test empty string: Proj(String, 0, "") should give List.nil
    let proj_empty = Expr::proj(string_name.clone(), 0, Expr::str_lit(""));
    let result_empty = tc.whnf(&proj_empty);

    assert!(
        !matches!(&result_empty.kind, ExprKind::Proj(..)),
        "Proj on empty string literal should reduce, but got unreduced Proj: {result_empty:?}"
    );

    let head_empty = result_empty.get_app_fn();
    assert!(
        matches!(&head_empty.kind, ExprKind::Const(n, _) if n == &Name::from_string("List.nil")),
        "Projected field of empty string should be List.nil, got head: {head_empty:?}"
    );
}

#[test]
fn test_proj_string_literal_lowering_with_transparency() {
    use crate::env::TransparencyMode;

    let env = build_string_env();
    let tc = TypeChecker::new(&env);
    let string_name = Name::from_string("String");

    for mode in [
        TransparencyMode::Reducible,
        TransparencyMode::Instances,
        TransparencyMode::Default,
        TransparencyMode::All,
    ] {
        let proj = Expr::proj(string_name.clone(), 0, Expr::str_lit("hi"));
        let result = tc.whnf_with_transparency(&proj, mode);

        assert!(
            !matches!(&result.kind, ExprKind::Proj(..)),
            "Proj on string literal should reduce in mode {mode:?}, got: {result:?}"
        );

        let head = result.get_app_fn();
        assert!(
            matches!(&head.kind, ExprKind::Const(n, _) if n == &Name::from_string("List.cons")),
            "Projected field should be List.cons in mode {mode:?}, got head: {head:?}"
        );
    }

    let proj_empty = Expr::proj(string_name, 0, Expr::str_lit(""));
    let result_empty = tc.whnf_with_transparency(&proj_empty, TransparencyMode::Default);
    assert!(
        !matches!(&result_empty.kind, ExprKind::Proj(..)),
        "Proj on empty string literal should reduce in transparency mode"
    );

    let head_empty = result_empty.get_app_fn();
    assert!(
        matches!(&head_empty.kind, ExprKind::Const(n, _) if n == &Name::from_string("List.nil")),
        "Projected field of empty string should be List.nil, got head: {head_empty:?}"
    );
}

/// Test that projection on constructor-form string (String.mk <list>) still works.
/// This verifies no regression from adding string literal lowering.
#[test]
fn test_proj_string_constructor_form() {
    let env = build_string_env();
    let tc = TypeChecker::new(&env);

    let string_name = Name::from_string("String");
    let char_const = Expr::const_(Name::from_string("Char"), vec![]);
    let list_nil = Expr::app(
        Expr::const_(Name::from_string("List.nil"), vec![Level::zero()]),
        char_const.clone(),
    );

    // Build String.mk (List.nil Char) — constructor form directly
    let string_mk = Expr::const_(Name::from_string("String.mk"), vec![]);
    let ctor_form = Expr::app(string_mk, list_nil.clone());

    // Proj(String, 0, String.mk (List.nil Char)) should give List.nil Char
    let proj = Expr::proj(string_name, 0, ctor_form);
    let result = tc.whnf(&proj);

    assert!(
        !matches!(&result.kind, ExprKind::Proj(..)),
        "Proj on String.mk constructor should reduce, got: {result:?}"
    );

    let head = result.get_app_fn();
    assert!(
        matches!(&head.kind, ExprKind::Const(n, _) if n == &Name::from_string("List.nil")),
        "Projected field should be List.nil, got head: {head:?}"
    );
}

/// Regression test for #1441: projection string literal lowering must use the
/// caller's transparency mode, not Default.
///
/// Before the fix, the projection reducer called `whnf_impl` (Default/Full
/// mode) to reduce string literals, ignoring the caller's
/// `TransparencyMode`. After the fix, it calls the transparency-aware WHNF
/// path with the caller's mode.
///
/// We verify this by checking that `whnf_impl` is NOT invoked when the entire
/// projection reduction goes through the `whnf_with_transparency` path.
#[test]
fn test_proj_string_literal_lowering_uses_caller_transparency_mode() {
    use crate::env::TransparencyMode;

    let env = build_string_env();
    let tc = TypeChecker::new(&env);
    let string_name = Name::from_string("String");

    // Reset the whnf_impl call counter.
    tc.reset_whnf_impl_call_count_for_tests();
    assert_eq!(tc.whnf_impl_call_count_for_tests(), 0);

    // Reduce a string-literal projection through whnf_with_transparency.
    // This exercises the shared projection reducer's string lowering path.
    let proj = Expr::proj(string_name, 0, Expr::str_lit("a"));
    let result = tc.whnf_with_transparency(&proj, TransparencyMode::Reducible);

    // The projection must have reduced (not stuck).
    assert!(
        !matches!(&result.kind, ExprKind::Proj(..)),
        "Proj on string literal should reduce via whnf_with_transparency, got: {result:?}"
    );

    // Key regression assertion (#1441): whnf_impl (Default path) must NOT have
    // been called. Before the fix, the projection reducer called whnf_impl for
    // string lowering, which would increment this counter. After the fix, it
    // calls whnf_with_transparency_impl instead, leaving the counter at 0.
    assert_eq!(
        tc.whnf_impl_call_count_for_tests(),
        0,
        "projection reduction should use whnf_with_transparency_impl (not whnf_impl) \
         for string literal lowering when called from the WithTransparency path"
    );
}

/// Regression test for #3209: projection reduction must NOT check that the
/// constructor's inductive name matches the Proj's struct_name.
///
/// In Lean 4, type aliases create situations where Proj("Alias", 0, e) has
/// e that WHNFs to a constructor for the underlying type, not the alias.
/// For example, `Substring` might be an alias for `Substring.Raw`, so
/// `Proj("Substring", 0, x)` where x reduces to `Substring.Raw.mk(...)`.
///
/// Lean 4 type_checker.cpp:358-373 (`reduce_proj_core`) does NOT check
/// the struct name — it only checks that the head is a constructor and
/// that the field index is in bounds.
///
/// Before this fix, clean had an extra `ctor_val.inductive_name == struct_name`
/// check that prevented these projections from reducing, causing TypeMismatch
/// errors on 5 Init module constants.
#[test]
fn test_proj_reduces_across_type_alias_boundary() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    // Define the "real" type: RealPair : Type
    // RealPair.mk : Prop → Prop → RealPair
    let real_pair = Name::from_string("RealPair");
    let real_pair_mk_type = Expr::arrow(
        Expr::prop(),
        Expr::arrow(Expr::prop(), Expr::const_(real_pair.clone(), vec![])),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: real_pair.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: Name::from_string("RealPair.mk"),
                type_: real_pair_mk_type,
            }],
        }],
    };
    env.add_inductive(decl).unwrap();

    let tc = TypeChecker::new(&env);

    // Build RealPair.mk val0 val1
    let mk = Expr::const_(Name::from_string("RealPair.mk"), vec![]);
    let val0 = Expr::prop();
    let val1 = Expr::type_();
    let pair_val = Expr::app(Expr::app(mk, val0.clone()), val1.clone());

    // Key scenario: Proj uses an ALIAS name, not the real inductive name.
    // This simulates the type alias pattern where Proj("AliasPair", 0, ...)
    // has a constructor from "RealPair" as the head.
    let alias_name = Name::from_string("AliasPair");

    // Proj("AliasPair", 0, RealPair.mk val0 val1) should STILL reduce
    // because Lean 4 does NOT check struct_name == constructor's inductive.
    let proj0 = Expr::proj(alias_name.clone(), 0, pair_val.clone());
    let result0 = tc.whnf(&proj0);
    assert_eq!(
        result0, val0,
        "Proj with alias name should reduce to field 0 (Part of #3209)"
    );

    let proj1 = Expr::proj(alias_name, 1, pair_val);
    let result1 = tc.whnf(&proj1);
    assert_eq!(
        result1, val1,
        "Proj with alias name should reduce to field 1 (Part of #3209)"
    );
}
